create index if not exists idx_asset_accounts_user_status on public.asset_accounts(user_id,status); create index if not exists idx_lots_user_asset_status on public.lots(user_id,asset_account_id,status); create index if not exists idx_transactions_user_asset_date on public.transactions(user_id,asset_account_id,transaction_date desc); create index if not exists idx_zakat_assessments_user_date on public.zakat_assessments(user_id,assessment_date desc,created_at desc); create index if not exists idx_zakat_assessment_lines_assessment on public.zakat_assessment_lines(assessment_id); create index if not exists idx_zakat_assessment_lines_lot on public.zakat_assessment_lines(lot_id); create index if not exists idx_zakat_payments_user_date on public.zakat_payments(user_id,payment_date desc); create index if not exists idx_zakat_payment_allocations_user_assessment on public.zakat_payment_allocations(user_id,assessment_id); create index if not exists idx_zakat_payment_allocations_asset on public.zakat_payment_allocations(asset_account_id);